from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[1]; BASE="https://raptorconsultinggroup.com"
def update_schema(text,url,crumbs,kind):
 m=re.search(r'<script data-raptor-schema="v[234]" type="application/ld\+json">(.*?)</script>',text,re.S); data=json.loads(m.group(1)); g=data['@graph']; canonical=BASE+url
 org=next(x for x in g if x.get('@id')==BASE+'/#organization'); org['founder']={"@id":BASE+'/about/ricardo-canilao/#person'}
 person=next((x for x in g if x.get('@id')==BASE+'/about/ricardo-canilao/#person'),None)
 if person is None:
  person={"@type":"Person","@id":BASE+"/about/ricardo-canilao/#person"}; g.append(person)
 person.update({"name":"Ricardo Canilao","url":BASE+"/about/ricardo-canilao/","jobTitle":"Senior Digital Consultant","worksFor":{"@id":BASE+"/#organization"},"homeLocation":{"@type":"AdministrativeArea","name":"Orange County, California"},"knowsAbout":["Technical SEO","Search architecture","Structured data","Web operations","Website production management","Shopify","Ecommerce systems","Website migration","Digital analytics"]})
 page=next((x for x in g if x.get('@id')==canonical+'#webpage'),None)
 if page:
  page['about']={"@id":person['@id']} if kind=='profile' else {"@id":org['@id']}
  page['mainEntity']={"@id":person['@id']} if kind=='profile' else {"@id":org['@id']}
 bc=next((x for x in g if x.get('@type')=='BreadcrumbList' and x.get('@id')==canonical+'#breadcrumb'),None)
 if bc is None: bc={"@type":"BreadcrumbList","@id":canonical+'#breadcrumb'}; g.append(bc)
 bc['itemListElement']=[{"@type":"ListItem","position":i,"name":name,"item":BASE+(dest or url)} for i,(name,dest) in enumerate(crumbs,1)]
 if page: page['breadcrumb']={"@id":bc['@id']}
 rep='<script data-raptor-schema="v5" type="application/ld+json">'+json.dumps(data,separators=(',',':'))+'</script>'; return text[:m.start()]+rep+text[m.end():]
def visible(items):
 parts=[]
 for name,url in items:
  if parts: parts.append('<span aria-hidden="true">//</span>')
  parts.append(f'<a href="{url}">{name}</a>' if url else f'<span>{name}</span>')
 return '<nav aria-label="Breadcrumb" class="breadcrumb">'+''.join(parts)+'</nav>'

# Company About
f=ROOT/'about/index.html'; text=f.read_text(encoding='utf-8'); crumbs=[('Home','/'),('About',None)]
text=re.sub(r'<nav aria-label="Breadcrumb" class="breadcrumb">.*?</nav>',visible(crumbs),text,count=1,flags=re.S)
if 'founder-profile-bridge' not in text:
 block='''<section aria-labelledby="founder-profile-title" class="section shell founder-profile-bridge"><div class="section-label">Personnel // Founder</div><h2 id="founder-profile-title">Ricardo Canilao</h2><p class="lead">Raptor is led by Ricardo Canilao, a senior digital consultant whose background spans technical SEO, ecommerce, website production, analytics, migrations, and large website portfolios.</p><div class="hero-actions"><a class="button button-primary" href="/about/ricardo-canilao/">View Founder Profile</a><a class="button button-secondary" href="/work/">Review Operating Evidence</a></div></section>'''
 text=text.replace('<section aria-labelledby="contact-title"',block+'<section aria-labelledby="contact-title"',1)
text=update_schema(text,'/about/',crumbs,'about'); f.write_text(text,encoding='utf-8')

# Founder profile receives a complete evidence-based page.
f=ROOT/'about/ricardo-canilao/index.html'; text=f.read_text(encoding='utf-8'); crumbs=[('Home','/'),('About','/about/'),('Ricardo Canilao',None)]
main='''<main id="main-content"><section class="service-hero section shell"><nav aria-label="Breadcrumb" class="breadcrumb"><a href="/">Home</a><span aria-hidden="true">//</span><a href="/about/">About</a><span aria-hidden="true">//</span><span>Ricardo Canilao</span></nav><div class="eyebrow">Personnel // Founder</div><h1>Ricardo Canilao</h1><p class="service-hero-lede">Senior Digital Consultant and founder of Raptor Consulting Group.</p><p class="service-hero-support">Technical SEO, web operations, ecommerce systems, production management, analytics, and digital infrastructure informed by firsthand operating work.</p><div class="hero-actions"><a class="button button-primary" href="/work/">View Operating Evidence</a><a class="button button-secondary" href="/contact/">Contact Ricardo</a></div></section><div class="divider shell"></div><section aria-labelledby="founder-disciplines-title" class="section shell"><div class="section-label">Disciplines // Working Range</div><h2 id="founder-disciplines-title">Technical depth across the systems surrounding the website.</h2><div class="service-card-grid"><article class="service-card"><h3>Technical SEO</h3><p>Diagnosis, search architecture, structured data, analytics, implementation, and post-change verification.</p></article><article class="service-card"><h3>Web Operations</h3><p>High-volume production, multi-site management, development, migrations, hosting, and quality control.</p></article><article class="service-card"><h3>Ecommerce Systems</h3><p>Shopify development, product operations, merchant systems, analytics, and ongoing store work.</p></article></div></section><section aria-labelledby="founder-experience-title" class="section section-deep"><div class="shell"><div class="section-label">Experience // Evidence-Labeled Scale</div><h2 id="founder-experience-title">Operating experience that shaped Raptor.</h2><div class="service-card-grid"><article class="service-card"><h3>15+ years in ecommerce</h3><p>Product, merchant, storefront, catalog, analytics, and operating work across changing ecommerce environments.</p></article><article class="service-card"><h3>Thousands of websites</h3><p>Production, technical support, quality control, implementation, launch, and post-production work across a large website volume.</p></article><article class="service-card"><h3>Approximately 4,000 web properties</h3><p>Contributed within a large portfolio and migration program, with direct responsibility for special projects, ecommerce properties, and two corporate websites.</p></article><article class="service-card"><h3>High-volume production</h3><p>Supported an operation moving roughly 30 websites per week while directly handling approximately 10 to 15 higher-touch projects.</p></article></div></div></section><section aria-labelledby="founder-proof-title" class="section shell"><div class="section-label">Evidence // Selected Work</div><h2 id="founder-proof-title">Claims connected to inspectable operating records.</h2><div class="hero-actions"><a class="button button-secondary" href="/work/case-studies/specialized-accounting-search-architecture/">Search Architecture Case</a><a class="button button-secondary" href="/work/case-studies/website-infrastructure-migration/">Migration Case</a><a class="button button-secondary" href="/work/case-studies/high-volume-website-production/">Production Case</a><a class="button button-secondary" href="/work/case-studies/wordpress-shopify-commerce-system/">Commerce Case</a></div></section><section aria-labelledby="founder-method-title" class="section shell"><div class="section-label">Operating Standard // HQCP</div><h2 id="founder-method-title">Detection is not diagnosis.</h2><p class="lead">Ricardo uses Raptor's Human Quality Control Protocol to separate automated detection from inspection, reproduction, corroboration, verification, priority, and implementation decisions.</p><div class="hero-actions"><a class="button button-primary" href="/work/systems/hqcp/">View HQCP</a><a class="button button-secondary" href="/services/search-systems/technical-seo/system-audit/">View System Audit</a></div></section><section class="section shell contact"><div class="contact-panel"><div><div class="section-label">Direct Contact</div><h2>Discuss the website problem directly with Ricardo.</h2><p>Call or email Raptor. No intake form required.</p></div><div class="contact-actions"><a class="button button-primary" data-contact-action="call" href="#">Call Raptor</a><a class="button button-secondary" data-contact-action="text" href="#">Text Raptor</a><a class="button button-secondary" href="mailto:raptorsystems.ai@gmail.com">Email Raptor</a></div></div></section></main>'''
text=re.sub(r'<main id="main-content">.*?</main>',main,text,count=1,flags=re.S); text=update_schema(text,'/about/ricardo-canilao/',crumbs,'profile'); f.write_text(text,encoding='utf-8')

# Contact hierarchy and entity relationship.
f=ROOT/'contact/index.html'; text=f.read_text(encoding='utf-8'); crumbs=[('Home','/'),('Contact',None)]
text=re.sub(r'<nav aria-label="Breadcrumb" class="breadcrumb">.*?</nav>',visible(crumbs),text,count=1,flags=re.S); text=update_schema(text,'/contact/',crumbs,'contact'); f.write_text(text,encoding='utf-8')
print('Finalized Company, Founder, and Contact architecture')
